AssistantMessageToolRequest(name='create', tool_call_id='function-call-17475f22-3e53-4418-ba33-4fb03efbac89', arguments={'file_text': '/* Custom Properties */
:root {
    --color-primary: #111827;
    --color-secondary: #4b5563;
    --color-bg: #ffffff;
    --color-bg-alt: #f3f4f6;
    --color-accent: #2563eb;
    --color-sale: #b91c1c; /* High contrast red */
    --color-text: #1f2937;
    --color-text-light: #4b5563;
    --font-sans: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

/* Reset & Base */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: var(--font-sans);
    color: var(--color-text);
    background-color: var(--color-bg);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
}

img {
    max-width: 100%;
    display: block;
    height: auto;
}

a {
    color: var(--color-primary);
    text-decoration: none;
}

a:hover {
    text-decoration: underline;
}

button {
    font-family: inherit;
    cursor: pointer;
    border: none;
    background: none;
}

/* Accessibility */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--color-primary);
    color: white;
    padding: 8px;
    z-index: 100;
    transition: top 0.2s;
    font-weight: 600;
}

.skip-link:focus {
    top: 0;
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

#main-content:focus {
    outline: none;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

/* Focus styles for keyboard navigation */
:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

/* Layout */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 16px;
}

.section {
    padding: 64px 0;
}

.section-title {
    font-size: 2rem;
    margin-bottom: 32px;
    font-weight: 700;
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 12px 24px;
    font-weight: 600;
    border-radius: 4px;
    text-decoration: none;
    transition: background-color 0.2s, color 0.2s;
}

.btn:hover {
    text-decoration: none;
}

.btn-primary {
    background-color: var(--color-primary);
    color: white;
}

.btn-primary:hover {
    background-color: #000;
}

.btn-secondary {
    background-color: var(--color-bg-alt);
    color: var(--color-primary);
}

.btn-secondary:hover {
    background-color: #e5e7eb;
}

.btn-outline {
    border: 2px solid var(--color-primary);
    color: var(--color-primary);
    background: transparent;
}

.btn-outline:hover {
    background-color: var(--color-primary);
    color: white;
}

/* Header */
.site-header {
    border-bottom: 1px solid #e5e7eb;
    padding: 16px 0;
    position: sticky;
    top: 0;
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(8px);
    z-index: 50;
}

.header-inner {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: -0.05em;
}

.logo:hover {
    text-decoration: none;
}

.nav-links {
    display: flex;
    list-style: none;
    gap: 24px;
}

.nav-links a {
    font-weight: 600;
    color: var(--color-secondary);
}

.nav-links a:hover {
    color: var(--color-primary);
}

.header-actions {
    display: flex;
    gap: 16px;
}

.icon-btn {
    font-size: 1.25rem;
    padding: 8px;
    border-radius: 50%;
}

.icon-btn:hover {
    background-color: var(--color-bg-alt);
}

/* Hero */
.hero {
    background-color: var(--color-bg-alt);
    padding: 120px 0;
    text-align: center;
}

.hero-content {
    max-width: 600px;
    margin: 0 auto;
}

.hero h1 {
    font-size: 3rem;
    font-weight: 800;
    line-height: 1.1;
    margin-bottom: 24px;
}

.hero p {
    font-size: 1.25rem;
    color: var(--color-secondary);
    margin-bottom: 32px;
}

/* Products */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 32px;
}

.product-card {
    display: flex;
    flex-direction: column;
}

.product-image-container {
    position: relative;
    aspect-ratio: 1;
    background-color: var(--color-bg-alt);
    border-radius: 8px;
    overflow: hidden;
    margin-bottom: 16px;
}

.product-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.3s ease;
}

.product-card:hover .product-image {
    transform: scale(1.05);
}

.badge-sale {
    position: absolute;
    top: 12px;
    right: 12px;
    background-color: var(--color-sale);
    color: white;
    padding: 4px 8px;
    font-size: 0.875rem;
    font-weight: 700;
    border-radius: 4px;
    text-transform: uppercase;
}

.product-details {
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.product-title {
    font-size: 1.125rem;
    font-weight: 600;
    margin-bottom: 8px;
}

.product-pricing {
    margin-bottom: 16px;
    display: flex;
    gap: 8px;
    align-items: center;
}

.price {
    font-weight: 600;
}

.sale-price {
    color: var(--color-sale);
}

.original-price {
    color: var(--color-text-light);
    font-size: 0.875rem;
    font-weight: 400;
}

.add-to-cart {
    margin-top: auto;
    width: 100%;
}

/* Deals */
.deals-section {
    background-color: #fef2f2;
}

/* Editorial */
.editorial-inner {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 48px;
    align-items: center;
}

.editorial-content h2 {
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: 24px;
}

.editorial-content p {
    font-size: 1.125rem;
    color: var(--color-secondary);
    margin-bottom: 32px;
}

.editorial-image {
    border-radius: 12px;
    overflow: hidden;
}

.editorial-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* Footer */
.site-footer {
    background-color: var(--color-primary);
    color: white;
    padding: 64px 0 32px;
}

.site-footer a {
    color: #d1d5db;
}

.site-footer a:hover {
    color: white;
    text-decoration: underline;
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 32px;
    margin-bottom: 48px;
}

.footer-grid h3 {
    font-size: 1.125rem;
    margin-bottom: 16px;
    font-weight: 600;
}

.footer-grid p {
    color: #d1d5db;
}

.footer-grid ul {
    list-style: none;
}

.footer-grid ul li {
    margin-bottom: 12px;
}

.footer-bottom {
    border-top: 1px solid #374151;
    padding-top: 32px;
    text-align: center;
    color: #9ca3af;
    font-size: 0.875rem;
}

/* Responsive */
@media (max-width: 768px) {
    .nav-links {
        display: none;
    }

    .editorial-inner {
        grid-template-columns: 1fr;
    }

    .hero {
        padding: 80px 0;
    }

    .hero h1 {
        font-size: 2.25rem;
    }
}
