const fs = require('fs');
const jsdom = require('jsdom');
const { JSDOM } = jsdom;
const axe = require('axe-core');

const html = fs.readFileSync('index.html', 'utf8');
const appJs = fs.readFileSync('app.js', 'utf8');

// Replace the script tags that load from CDN with local execution where possible, or just let jsdom run scripts.
const dom = new JSDOM(html, {
  runScripts: "dangerously",
  resources: "usable"
});

// Since JSDOM doesn't transpile babel well out of the box with the standalone script (due to timeouts/async), 
// we might get timeout. Let's see.
dom.window.onload = () => {
  setTimeout(() => {
      axe.run(dom.window.document.documentElement, (err, results) => {
        if (err) throw err;
        if (results.violations.length > 0) {
            console.error('Violations:', JSON.stringify(results.violations, null, 2));
            process.exit(1);
        } else {
            console.log('No accessibility violations found!');
            process.exit(0);
        }
      });
  }, 3000);
};

